import{_ as e,o as s,c as i,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const c=JSON.parse('{"title":"Atualizações","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/updates.md","filePath":"pt-BR/guide/updates.md"}'),t={name:"pt-BR/guide/updates.md"};function r(n,a,d,l,p,u){return s(),i("div",null,[...a[0]||(a[0]=[o(`<h1 id="atualizacoes" tabindex="-1">Atualizações <a class="header-anchor" href="#atualizacoes" aria-label="Permalink to &quot;Atualizações&quot;">​</a></h1><p>O Orbit se atualiza em <strong>Configurações → Atualizações do Orbit</strong>. Rodar o <code>install.sh</code> de novo também funciona: ele instala a versão mais recente, ou a de <code>ORBIT_VERSION</code>, e confere o arquivo com o <code>SHA256SUMS</code>, mas, diferente do console, não confere a assinatura.</p><h2 id="preflight" tabindex="-1">Antes de começar <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Antes de começar {#preflight}&quot;">​</a></h2><p>Uma atualização só começa depois de uma verificação sem nada bloqueando:</p><table tabindex="0"><thead><tr><th>Verificação</th><th>Bloqueia quando</th></tr></thead><tbody><tr><td>Assinatura da versão</td><td>A versão não está assinada com a chave de versões do Orbit</td></tr><tr><td>Caminho de upgrade</td><td>A versão não é mais nova que a que está rodando</td></tr><tr><td>Disco livre</td><td>Menos de 2 GB livres para o download, o backup e os binários antigos</td></tr><tr><td>Backup dos metadados</td><td>Nunca bloqueia; avisa quando o último tem mais de um dia</td></tr><tr><td>Operações rodando</td><td>Deploys, backups ou outras operações ainda estão rodando</td></tr><tr><td>Agente</td><td>O agente do servidor está offline</td></tr></tbody></table><p>O console confere de novo logo antes de começar, e só uma atualização roda por vez.</p><p>Uma operação que parou sem terminar, depois de o Orbit reiniciar ou de passar do limite de 30 minutos, não bloqueia atualizações por muito tempo: o Orbit confere a cada cinco minutos, e a cada vez que inicia, se cada operação rodando ainda está sendo executada, e marca as que não estão como falhas, com o botão <strong>Tentar de novo</strong>.</p><h2 id="steps" tabindex="-1">O que uma atualização faz <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;O que uma atualização faz {#steps}&quot;">​</a></h2><ol><li><strong>Faz backup dos dados do Orbit</strong> em <code>/var/lib/orbit/backups/metadata/</code>, o mesmo arquivo que o <code>orbit backup</code> escreve.</li><li><strong>Baixa a versão</strong> e <strong>a verifica:</strong> o <code>SHA256SUMS</code> precisa ter uma assinatura Ed25519 válida da chave de versões fixada no Orbit em execução, e o arquivo precisa bater com o hash dele. Uma versão sem assinatura, adulterada ou incompleta para aqui, e nada no servidor mudou.</li><li><strong>Reinicia o Orbit na versão nova,</strong> guardando os binários anteriores como <code>orbit.previous</code> e <code>orbit-agent.previous</code>. O console desconecta por alguns segundos e reconecta sozinho. As aplicações e os bancos continuam rodando.</li><li><strong>Aplica as migrações</strong> em ordem, registrando cada uma ao terminar.</li><li><strong>Verifica a atualização:</strong> o esquema, a API, o fluxo de eventos e o agente do servidor.</li></ol><p>A atualização pode ser cancelada enquanto faz backup, baixa e verifica a versão, não depois.</p><p>Se a versão nova nunca subir, uma proteção preparada antes do reinício traz de volta os binários anteriores e o backup de antes da atualização depois de 3 minutos, sobe a versão anterior, e o console diz por que a atualização falhou.</p><h2 id="interrupted" tabindex="-1">Se uma atualização for interrompida <a class="header-anchor" href="#interrupted" aria-label="Permalink to &quot;Se uma atualização for interrompida {#interrupted}&quot;">​</a></h2><p>Se o console não estiver disponível, no servidor:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                # versão, instalação, operações em andamento</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # retomar: a atualização continua da última etapa</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rollback</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # voltar os binários anteriores e o backup de antes da atualização</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orbit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1 hour ago&quot;</span></span></code></pre></div><ul><li><p><strong>Retome</strong> quando a causa foi temporária (o servidor reiniciou, o disco encheu e foi liberado). A atualização continua de onde parou, e migrações já aplicadas não são aplicadas de novo.</p></li><li><p><strong>Volte atrás</strong> quando o problema é a própria versão. Voltar atrás restaura o backup feito por esta atualização, então o que mudou no Orbit depois que ela começou se perde. As aplicações e os bancos delas não são tocados.</p></li><li><p><strong>Reinstalar uma versão à mão:</strong></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/getcortexlabs/orbit-releases/releases/latest/download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ORBIT_VERSION=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versã</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span></span></code></pre></div></li></ul><h2 id="limits" tabindex="-1">O que uma atualização não cobre <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;O que uma atualização não cobre {#limits}&quot;">​</a></h2><p>Com um servidor principal só, o console do Orbit fica indisponível enquanto ele reinicia, e uma atualização não protege contra a perda desse servidor. Mantenha uma cópia do <a href="./operating#backup"><code>orbit backup</code></a> fora do servidor.</p>`,17)])])}const k=e(t,[["render",r]]);export{c as __pageData,k as default};
